SET NOCOUNT ON;

-- =============================================================================
-- R__organizacion_seed_01.sql
-- Seed idempotente para catálogos del esquema organizacion.
-- Estrategia: MERGE simple con MATCH por id_* + IDENTITY_INSERT.
-- No incluye DELETE de huérfanos.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- cat_tipo_organismo
-- Valores documentados en Diseño_Modelo_Datos_SIP_v1_0:
-- POLICIA, FISCALIA, TRIBUNAL, LABORATORIO, AGENCIA_GOB, INT_INTERNACIONAL, OTRO
-- -----------------------------------------------------------------------------
SET IDENTITY_INSERT organizacion.cat_tipo_organismo ON;
MERGE organizacion.cat_tipo_organismo AS target
USING (VALUES
 (1, N'POLICIA', N'Policía'),
 (2, N'FISCALIA', N'Fiscalía'),
 (3, N'TRIBUNAL', N'Tribunal'),
 (4, N'LABORATORIO', N'Laboratorio'),
 (5, N'AGENCIA_GOB', N'Agencia gubernamental'),
 (6, N'INT_INTERNACIONAL', N'Organismo internacional'),
 (7, N'OTRO', N'Otro')
) AS src (id_tipo_organismo, codigo, descripcion)
ON target.id_tipo_organismo = src.id_tipo_organismo
WHEN MATCHED THEN UPDATE SET target.codigo = src.codigo, target.descripcion = src.descripcion
WHEN NOT MATCHED THEN INSERT (id_tipo_organismo, codigo, descripcion) VALUES (src.id_tipo_organismo, src.codigo, src.descripcion);
SET IDENTITY_INSERT organizacion.cat_tipo_organismo OFF;

-- -----------------------------------------------------------------------------
-- cat_nivel_organismo
-- Valores documentados: NACIONAL, REGIONAL, INTERNACIONAL
-- -----------------------------------------------------------------------------
SET IDENTITY_INSERT organizacion.cat_nivel_organismo ON;
MERGE organizacion.cat_nivel_organismo AS target
USING (VALUES
 (1, N'NACIONAL', N'Nacional'),
 (2, N'REGIONAL', N'Regional'),
 (3, N'INTERNACIONAL', N'Internacional')
) AS src (id_nivel_organismo, codigo, descripcion)
ON target.id_nivel_organismo = src.id_nivel_organismo
WHEN MATCHED THEN UPDATE SET target.codigo = src.codigo, target.descripcion = src.descripcion
WHEN NOT MATCHED THEN INSERT (id_nivel_organismo, codigo, descripcion) VALUES (src.id_nivel_organismo, src.codigo, src.descripcion);
SET IDENTITY_INSERT organizacion.cat_nivel_organismo OFF;

