MERGE organizacion.cat_tipo_unidad AS target
USING (VALUES
 (1, 'BRI', 'Brigada'),
 (2, 'JN', 'Jefatura nacional'),
 (3, 'PREF', 'Prefectura'),
 (4, 'DEPTO', 'Departamento')
) AS src (id_tipo_unidad, codigo, nombre)
ON target.id_tipo_unidad = src.id_tipo_unidad
WHEN MATCHED THEN UPDATE SET target.codigo = src.codigo, target.nombre = src.nombre
WHEN NOT MATCHED THEN INSERT (id_tipo_unidad, codigo, nombre) VALUES (src.id_tipo_unidad, src.codigo, src.nombre);

